window.CONCEPT_KEYS = Object.assign(window.CONCEPT_KEYS || {}, {
  'abd-exam': { gist: 'Look → listen → touch. Leak = cell injury; back-up = blocked duct; can’t make or clear = liver failing.', zk: ['Quadrant tells the organ', 'Muscularis moves gas = bowel sounds', 'Injured cells leak enzymes', 'Direct bilirubin backs up · NH₃ → urea'] },
  scopes: { gist: 'Sedation slows breathing; the throat spray removes the gag — watch RR during, withhold sips after.', zk: ['EGD, ERCP, colonoscopy, capsule', 'Gag reflex guards the airway', 'Brainstem drive depressed', 'GABA-A, mu-opioid · PEG holds water'] },
  stomatitis: { gist: 'Fast-renewing lining: stop division (chemo) or lose flora (Candida) → ulcers; won’t heal → cancer.', zk: ['Saliva washes and buffers', 'Lining renews every few days', 'Chemo kills basal cells', 'Ergosterol · Na⁺ channels · p53'] },
  gerd: { gist: 'LES pressure must beat stomach pressure; reflux heals as Barrett’s or scar.', zk: ['LES + diaphragm hold contents down', 'Squamous meets columnar', 'Metaplasia → Barrett’s', 'ACh contracts, NO relaxes the LES'] },
  pud: { gist: 'Prostaglandin barrier fails (NSAIDs, H. pylori) → acid and pepsin erode the wall.', zk: ['Stomach + duodenum', 'Mucus–bicarbonate barrier', 'Parietal, chief, G cells', 'COX-1 · urease makes ammonia'] },
  ugib: { gist: 'Volume first in a bleed; after gastrectomy the meal dumps — fluid shift early, insulin overshoot late.', zk: ['Arteries under the ulcer', 'Crater erodes a vessel', 'Baroreceptors → tachycardia', 'Hematin · osmosis · insulin overshoot'] },
  'ibs-hernia': { gist: 'IBS = oversensitive gut, no damage. Hernias and hemorrhoids = pressure from inside.', zk: ['Colon, groin, anal cushions', 'Weak fascia, slipped veins', 'Hypersensitive enteric nerves', '5-HT₃ · cGMP · chloride channels'] },
  crc: { gist: 'Polyp → cancer over years (screen!). Right = anemia, left = obstruction; stoma color = blood supply.', zk: ['Portal vein → liver spread', 'Liquid right, formed left', 'Adenoma → carcinoma', 'APC, mismatch repair · 5-FU, VEGF'] },
  obstruction: { gist: 'Blocked bowel leaks volume; colicky = fighting, constant = dying wall.', zk: ['Ileum blocks most', 'Swollen, leaky wall', 'Ischemic cells release endotoxin', 'HCl loss → alkalosis, K⁺ ↓'] },
  'acute-abd': { gist: 'Inflammation leaks fluid on purpose; when walling off fails → third spacing and septic shock.', zk: ['Appendix, peritoneum, small bowel', 'Fecalith → pressure → ischemia', 'Neutrophils, E. coli, norovirus', 'LPS, TNF · Na⁺–glucose cotransport'] },
  ibd: { gist: 'TNF-driven attack. UC = lining from the rectum (bleeds); Crohn’s = all layers in patches (scars, tunnels).', zk: ['Rectum up vs ileum patches', 'Mucosa vs transmural', 'T cells, macrophages, NOD2', 'TNF-α · integrins · 5-ASA'] },
  divert: { gist: 'Pressure makes pouches; trapped bacteria infect them. Gluten and parasites damage the villi.', zk: ['Sigmoid and small bowel', 'Mucosa herniates; villi flatten', 'Bacteria invade a pouch', 'Laplace · tTG + HLA-DQ2 · metronidazole'] },
  cirrhosis: { gist: 'Scar blocks portal flow (pressure backs up) and the liver can’t make albumin or clotting factors — ascites, bleeding, jaundice.', zk: ['Portal pressure 3 → ≥ 10 mm Hg', 'Fibrous bands + nodules', 'Stellate cells make collagen', 'Starling forces · aldosterone · vitamin K'] },
  'varices-he': { gist: 'The detour around the liver bursts thin veins and carries ammonia to the brain — lower pressure, stop bleeding, trap ammonia.', zk: ['Esophageal collaterals, TIPS', 'Thin-walled varices; swollen astrocytes', 'Gut bacteria make ammonia', 'NH₃ → NH₄⁺ · somatostatin · β-blockade'] },
  hepatitis: { gist: 'A and E through the gut, cleared; B, C, D through blood, smolder into cirrhosis and cancer.', zk: ['Swollen liver; transplant regrows', 'Lobular necrosis; > 6 months chronic', 'T cells kill infected hepatocytes', 'Reverse transcriptase · NS3/NS5A/NS5B'] },
  gallbladder: { gist: 'Concentrated bile → cholesterol stones; a stone in the cystic duct traps bile that burns the wall.', zk: ['Cystic duct, common bile duct, Oddi', 'Thick wall → gangrene', 'Cholesterol beyond bile salts', 'CCK · ursodiol · opioids tighten Oddi'] },
  pancreatitis: { gist: 'Trypsin turns on inside the gland → autodigestion: calcium lost, vessels bleed and leak → shock, ARDS.', zk: ['Retroperitoneal; head on the bile duct', 'Edema → necrosis; chronic fibrosis', 'Trypsinogen activated inside acinar cells', 'Elastase · lipase + Ca²⁺ soaps · kallikrein'] },
  'panc-cancer': { gist: 'Silent until the head tumor blocks the bile duct; the Whipple’s three joins can leak corrosive juice.', zk: ['Head → jaundice; Whipple removes a lot', 'Duct adenocarcinoma, nerve invasion', 'KRAS; tumor thromboplastin → clots', 'CA 19-9 · 5-FU · gemcitabine'] },
  undernutrition: { gist: 'Short on fuel, the body burns its own protein; feed safely — formula out of the lungs, refeed slowly.', zk: ['Gut first; TPN into a central vein', 'Muscle wastes, gut lining thins', 'Prealbumin falls first', 'Insulin drives PO₄³⁻, K⁺, Mg²⁺ into cells'] },
  obesity: { gist: 'Active fat drives appetite and inflammation; a steady deficit helps; bypass trades loss for supplements, leaks, dumping.', zk: ['1–2 oz pouch; duodenum bypassed', 'Central fat → liver, chest', 'Leptin resistance, cytokines', 'GLP-1 · lipase blocked · MC4R'] }
});

